module.exports = [
{ e: "🗼", art: { b: "🚀", s: ["🔥", "1️⃣", "2️⃣", "3️⃣"], c: ["#3A2A1B", "#E0802C"] },
pt: { h: "Leo empilhou três copos de plástico um em cima do outro e disse que era um foguete. O vovô gostou: “E sabe que os foguetes grandes são assim mesmo, em pedaços? Eles vão soltando as partes vazias no caminho, como uma corrida de revezamento!”", t: "O gigante Saturno V e os estágios", f: "Para ir à Lua, os americanos construíram o Saturno V, o foguete mais alto já usado em missões tripuladas: tinha 110 metros, mais que um prédio de 30 andares. Ele era dividido em três estágios. Quando o combustível de um estágio acabava, ele se soltava e caía, deixando o foguete mais leve para o próximo continuar.", x: "Na decolagem, o primeiro estágio do Saturno V queimava toneladas de combustível por segundo! O barulho era tão forte que podia ser sentido a quilômetros de distância.", s: ["Soltar as partes vazias deixa o foguete mais leve, e um foguete mais leve vai mais longe com menos combustível.", "No topo do Saturno V ficava a pequena cápsula onde os três astronautas viajavam.", "O Saturno V levou astronautas à Lua seis vezes."], ex: { t: "Foguete de dois estágios", m: "duas bexigas compridas, um copo de papel sem fundo (anel), barbante comprido, canudo, fita, duas cadeiras", p: ["Passe o barbante pelo canudo e amarre entre duas cadeiras bem afastadas.", "Encha a primeira bexiga até a metade, passe a boca dela pelo anel de papel e segure. Encha a segunda bexiga dentro do anel, de modo que ela prenda a boca da primeira.", "Prenda as bexigas no canudo com fita e solte: a de trás empurra primeiro e depois a da frente continua! Pode precisar de algumas tentativas."] }, at: "Emblema da missão 11", m: "papel, lápis de cor", p: ["Desenhe o Saturno V ao lado de um prédio e de uma pessoinha para comparar o tamanho.", "Separe o foguete em três partes coloridas e numere os estágios.", "Faça o emblema da missão 11."], q: "Que outras coisas você conhece que funcionam em etapas, uma depois da outra?" },
en: { h: "Leo stacked three plastic cups on top of each other and said it was a rocket. Grandpa liked it: “And did you know big rockets really are built in pieces? They drop the empty parts along the way, like a relay race!”", t: "The giant Saturn V and rocket stages", f: "To reach the Moon, Americans built the Saturn V, the tallest rocket ever used on crewed missions: it stood 110 meters (363 feet), taller than a 30-story building. It was divided into three stages. When one stage ran out of fuel, it detached and fell away, making the rocket lighter for the next one to carry on.", x: "At liftoff, the Saturn V's first stage burned tons of fuel every second! The noise was so powerful it could be felt miles away.", s: ["Dropping the empty parts makes the rocket lighter, and a lighter rocket goes farther on less fuel.", "At the top of the Saturn V sat the small capsule where the three astronauts traveled.", "The Saturn V carried astronauts to the Moon six times."], ex: { t: "Two-stage rocket", m: "two long balloons, a paper cup with the bottom cut out (a ring), long string, a straw, tape, two chairs", p: ["Thread the string through the straw and tie it between two chairs set far apart.", "Inflate the first balloon halfway, pass its neck through the paper ring and hold it. Inflate the second balloon inside the ring so it pinches the first balloon's neck shut.", "Tape the balloons to the straw and let go: the back one pushes first, then the front one keeps going! It may take a few tries."] }, at: "Mission patch 11", m: "paper, colored pencils", p: ["Draw the Saturn V next to a building and a tiny person to compare sizes.", "Split the rocket into three colored sections and number the stages.", "Make the mission 11 patch."], q: "What other things do you know that work in stages, one after another?" },
es: { h: "Leo apiló tres vasos de plástico uno encima del otro y dijo que era un cohete. Al abuelo le gustó: “¿Y sabías que los cohetes grandes son así, por partes? ¡Van soltando las partes vacías en el camino, como una carrera de relevos!”", t: "El gigante Saturno V y las etapas", f: "Para ir a la Luna, los estadounidenses construyeron el Saturno V, el cohete más alto usado en misiones tripuladas: medía 110 metros, más que un edificio de 30 pisos. Estaba dividido en tres etapas. Cuando se acababa el combustible de una, se soltaba y caía, dejando el cohete más liviano para que la siguiente continuara.", x: "¡Al despegar, la primera etapa del Saturno V quemaba toneladas de combustible por segundo! El ruido era tan fuerte que se podía sentir a kilómetros de distancia.", s: ["Soltar las partes vacías hace más liviano al cohete, y un cohete más liviano llega más lejos con menos combustible.", "Arriba del Saturno V estaba la pequeña cápsula donde viajaban los tres astronautas.", "El Saturno V llevó astronautas a la Luna seis veces."], ex: { t: "Cohete de dos etapas", m: "dos globos largos, un vaso de papel sin fondo (un anillo), cordel largo, pajita, cinta, dos sillas", p: ["Pasa el cordel por la pajita y átalo entre dos sillas bien separadas.", "Infla el primer globo hasta la mitad, pasa su boca por el anillo de papel y sostenla. Infla el segundo globo dentro del anillo, de modo que apriete la boca del primero.", "Pega los globos a la pajita con cinta y suéltalos: ¡el de atrás empuja primero y después el de adelante sigue! Puede que haga falta probar varias veces."] }, at: "Emblema de la misión 11", m: "papel, lápices de colores", p: ["Dibuja el Saturno V al lado de un edificio y una personita para comparar el tamaño.", "Divide el cohete en tres partes de colores y numera las etapas.", "Haz el emblema de la misión 11."], q: "¿Qué otras cosas conoces que funcionan por etapas, una después de otra?" } },

{ e: "🌕", art: { b: "🌕", s: ["👣", "🚩", "🌍", "👨‍🚀"], c: ["#1B1B2A", "#7A7A8A"] },
pt: { h: "O vovô contou que tinha a idade da Nina quando viu, numa TV em preto e branco, uma pessoa pisar na Lua. “Todo mundo parou para assistir”, lembrou, emocionado. “Até os vizinhos que não tinham TV vieram para a nossa sala.” Nina tentou imaginar o mundo inteiro olhando a mesma tela.", t: "Apollo 11: pessoas na Lua", f: "Em 20 de julho de 1969, a missão Apollo 11 pousou na Lua. Neil Armstrong foi o primeiro a pisar no solo lunar, seguido por Buzz Aldrin. Os dois caminharam lá fora por umas duas horas e meia, coletaram pedras e fizeram experimentos, enquanto Michael Collins esperava em órbita, na nave que os levaria de volta.", x: "Ao pisar na Lua, Armstrong disse: “É um pequeno passo para um homem, mas um salto gigante para a humanidade.” Centenas de milhões de pessoas assistiram ao vivo pela TV!", s: ["Ao todo, 12 pessoas caminharam na Lua, entre 1969 e 1972.", "Os astronautas trouxeram centenas de quilos de rochas lunares, estudadas até hoje.", "Como a gravidade da Lua é bem menor, os astronautas pulavam como cangurus."], ex: { t: "Pegada que dura para sempre", m: "uma bandeja com farinha, um sapato ou a mão, um canudo", p: ["Faça uma pegada caprichada na farinha, como a de um astronauta.", "Agora sopre de leve pelo canudo em volta da pegada, como se fosse o vento da Terra.", "O vento desmancha a pegada! Na Lua não há vento nem chuva, por isso as pegadas dos astronautas continuam lá até hoje."] }, at: "Emblema da missão 12", m: "papel, lápis de cor", p: ["Desenhe uma pegada na Lua com a Terra azul no céu escuro.", "Escreva: “Um pequeno passo, um salto gigante — 1969”.", "Guarde com os outros emblemas."], q: "Se você pisasse na Lua, qual seria a sua primeira frase?" },
en: { h: "Grandpa said he was Nina's age when he saw, on a black-and-white TV, a person step onto the Moon. “Everyone stopped to watch,” he remembered, moved. “Even neighbors without a TV came to our living room.” Nina tried to imagine the whole world watching the same screen.", t: "Apollo 11: people on the Moon", f: "On July 20, 1969, the Apollo 11 mission landed on the Moon. Neil Armstrong was the first to step onto the lunar surface, followed by Buzz Aldrin. They walked outside for about two and a half hours, collected rocks and did experiments, while Michael Collins waited in orbit in the spacecraft that would take them home.", x: "Stepping onto the Moon, Armstrong said: “That's one small step for man, one giant leap for mankind.” Hundreds of millions of people watched it live on TV!", s: ["In all, 12 people walked on the Moon between 1969 and 1972.", "The astronauts brought back hundreds of kilograms of Moon rocks, still being studied today.", "Because the Moon's gravity is much weaker, astronauts hopped around like kangaroos."], ex: { t: "A footprint that lasts forever", m: "a tray of flour, a shoe or your hand, a straw", p: ["Make a nice footprint in the flour, like an astronaut's.", "Now blow gently through the straw around the footprint, like Earth's wind.", "The wind wipes the footprint away! The Moon has no wind or rain, so the astronauts' footprints are still there today."] }, at: "Mission patch 12", m: "paper, colored pencils", p: ["Draw a footprint on the Moon with the blue Earth in the dark sky.", "Write: “One small step, one giant leap — 1969.”", "Keep it with your other patches."], q: "If you stepped onto the Moon, what would your first words be?" },
es: { h: "El abuelo contó que tenía la edad de Nina cuando vio, en una tele en blanco y negro, a una persona pisar la Luna. “Todo el mundo se paró a mirar”, recordó, emocionado. “Hasta los vecinos que no tenían tele vinieron a nuestra sala.” Nina intentó imaginar al mundo entero mirando la misma pantalla.", t: "Apolo 11: personas en la Luna", f: "El 20 de julio de 1969, la misión Apolo 11 alunizó. Neil Armstrong fue el primero en pisar el suelo lunar, seguido por Buzz Aldrin. Los dos caminaron afuera durante unas dos horas y media, juntaron piedras e hicieron experimentos, mientras Michael Collins esperaba en órbita, en la nave que los llevaría de vuelta.", x: "Al pisar la Luna, Armstrong dijo: “Es un pequeño paso para el hombre, pero un gran salto para la humanidad.” ¡Cientos de millones de personas lo vieron en vivo por televisión!", s: ["En total, 12 personas caminaron sobre la Luna, entre 1969 y 1972.", "Los astronautas trajeron cientos de kilos de rocas lunares, que se estudian hasta hoy.", "Como la gravedad de la Luna es mucho menor, los astronautas saltaban como canguros."], ex: { t: "Una huella que dura para siempre", m: "una bandeja con harina, un zapato o la mano, una pajita", p: ["Haz una huella prolija en la harina, como la de un astronauta.", "Ahora sopla suavemente con la pajita alrededor de la huella, como si fuera el viento de la Tierra.", "¡El viento deshace la huella! En la Luna no hay viento ni lluvia, por eso las huellas de los astronautas siguen allí hasta hoy."] }, at: "Emblema de la misión 12", m: "papel, lápices de colores", p: ["Dibuja una huella en la Luna con la Tierra azul en el cielo oscuro.", "Escribe: “Un pequeño paso, un gran salto — 1969”.", "Guárdalo con los otros emblemas."], q: "Si pisaras la Luna, ¿cuál sería tu primera frase?" } },

{ e: "🛠️", art: { b: "🛠️", s: ["⬛", "⚪", "🧑‍🚀", "🌍"], c: ["#4E1B0B", "#C2502C"] },
pt: { h: "Leo tentou encaixar uma peça quadrada num buraco redondo do brinquedo e desistiu, frustrado. O vovô sorriu: “Uma vez, a vida de três astronautas dependeu exatamente desse problema: encaixar uma peça quadrada num buraco redondo. E eles conseguiram!”", t: "Apollo 13: o resgate mais incrível", f: "Em abril de 1970, a nave Apollo 13 ia para a Lua quando um tanque de oxigênio explodiu. O astronauta disse a famosa frase: “Houston, tivemos um problema.” Sem conseguir pousar na Lua, os três astronautas usaram o módulo lunar como bote salva-vidas, contornaram a Lua e voltaram para a Terra em segurança.", x: "Os filtros que limpavam o ar da nave eram quadrados, e os do módulo lunar eram redondos. Os engenheiros na Terra inventaram um adaptador usando só o que havia na nave, como fita adesiva, plástico e a capa de um manual, e ensinaram os astronautas pelo rádio!", s: ["Os astronautas passaram muito frio, porque desligaram quase tudo para economizar energia.", "Milhares de pessoas trabalharam sem parar na Terra para salvar a tripulação.", "A Apollo 13 ficou conhecida como “o fracasso bem-sucedido”."], ex: { t: "Desafio Apollo 13", m: "uma caixa com materiais aleatórios: fita, papelão, sacolas, canudos, elásticos, clipes; um pote redondo e um objeto quadrado", p: ["O desafio: usando só os materiais da caixa, fazer o objeto quadrado encaixar e ficar firme na boca do pote redondo.", "Trabalhem em equipe e cronometrem 15 minutos.", "Testem a invenção! Como os engenheiros da Apollo 13, vocês resolveram um problema com o que tinham."] }, at: "Emblema da missão 13", m: "papel, lápis de cor", p: ["Desenhe a nave voltando para a Terra, com a Lua atrás.", "Escreva: “Houston, tivemos um problema… e resolvemos!”.", "Faça o emblema da missão 13."], q: "Conte uma vez em que você resolveu um problema usando criatividade." },
en: { h: "Leo tried to fit a square piece into a round hole in a toy and gave up, frustrated. Grandpa smiled: “Once, three astronauts' lives depended on exactly that problem: fitting a square piece into a round hole. And they did it!”", t: "Apollo 13: the most amazing rescue", f: "In April 1970, Apollo 13 was on its way to the Moon when an oxygen tank exploded. The astronaut said the famous words: “Houston, we've had a problem.” Unable to land on the Moon, the three astronauts used the lunar module as a lifeboat, swung around the Moon and returned safely to Earth.", x: "The filters that cleaned the air in the main spacecraft were square, and the ones in the lunar module were round. Engineers on Earth invented an adapter using only what was on board, like duct tape, plastic and a manual cover, and talked the astronauts through it by radio!", s: ["The astronauts got very cold, because they shut down almost everything to save power.", "Thousands of people on Earth worked nonstop to save the crew.", "Apollo 13 became known as “a successful failure.”"], ex: { t: "Apollo 13 challenge", m: "a box of random materials: tape, cardboard, bags, straws, rubber bands, paper clips; a round container and a square object", p: ["The challenge: using only the materials in the box, make the square object fit snugly over the mouth of the round container.", "Work as a team and set a timer for 15 minutes.", "Test your invention! Like the Apollo 13 engineers, you solved a problem with what you had."] }, at: "Mission patch 13", m: "paper, colored pencils", p: ["Draw the spacecraft heading back to Earth, with the Moon behind it.", "Write: “Houston, we had a problem… and we solved it!”", "Make the mission 13 patch."], q: "Tell about a time you solved a problem using creativity." },
es: { h: "Leo intentó meter una pieza cuadrada en un agujero redondo del juguete y se rindió, frustrado. El abuelo sonrió: “Una vez, la vida de tres astronautas dependió exactamente de ese problema: meter una pieza cuadrada en un agujero redondo. ¡Y lo lograron!”", t: "Apolo 13: el rescate más increíble", f: "En abril de 1970, la nave Apolo 13 iba hacia la Luna cuando explotó un tanque de oxígeno. El astronauta dijo la famosa frase: “Houston, tenemos un problema.” Sin poder alunizar, los tres astronautas usaron el módulo lunar como bote salvavidas, rodearon la Luna y volvieron a la Tierra sanos y salvos.", x: "¡Los filtros que limpiaban el aire de la nave eran cuadrados, y los del módulo lunar eran redondos! Los ingenieros en la Tierra inventaron un adaptador usando solo lo que había en la nave, como cinta adhesiva, plástico y la tapa de un manual, y se lo explicaron a los astronautas por radio.", s: ["Los astronautas pasaron mucho frío, porque apagaron casi todo para ahorrar energía.", "Miles de personas trabajaron sin parar en la Tierra para salvar a la tripulación.", "El Apolo 13 se conoció como “el fracaso exitoso”."], ex: { t: "Desafío Apolo 13", m: "una caja con materiales variados: cinta, cartón, bolsas, pajitas, gomitas, clips; un frasco redondo y un objeto cuadrado", p: ["El desafío: usando solo los materiales de la caja, lograr que el objeto cuadrado encaje y quede firme en la boca del frasco redondo.", "Trabajen en equipo y cronometren 15 minutos.", "¡Prueben el invento! Como los ingenieros del Apolo 13, resolvieron un problema con lo que tenían."] }, at: "Emblema de la misión 13", m: "papel, lápices de colores", p: ["Dibuja la nave volviendo a la Tierra, con la Luna detrás.", "Escribe: “Houston, tuvimos un problema… ¡y lo resolvimos!”.", "Haz el emblema de la misión 13."], q: "Cuenta una vez en que resolviste un problema usando la creatividad." } },

{ e: "🛰️", art: { b: "🛰️", s: ["🌍", "🧑‍🚀", "💧", "🌅"], c: ["#0B2A4E", "#3A6AB0"] },
pt: { h: "Leo viu um vídeo de astronautas brincando com bolhas de água flutuando no ar e quis saber por que nada caía lá dentro. “Na verdade, tudo está caindo!”, disse o vovô. “A estação, os astronautas e a água caem juntos, o tempo todo, em volta da Terra. Por isso eles flutuam.”", t: "A Estação Espacial Internacional", f: "A Estação Espacial Internacional é um laboratório enorme que dá voltas na Terra a uns 400 quilômetros de altura. Ela foi montada no espaço, peça por peça, por vários países. Desde novembro de 2000 sempre há pessoas morando lá, sem parar.", x: "A Estação Espacial é do tamanho de um campo de futebol! Nas noites certas, dá para vê-la da Terra a olho nu, como uma estrela brilhante que passa rápido pelo céu.", s: ["Na estação, os astronautas fazem experimentos com plantas, remédios, materiais e com o próprio corpo.", "Lá dentro, a sensação é de não ter peso, porque a estação e tudo dentro dela estão em queda livre ao redor da Terra.", "Astronautas de muitos países, inclusive um brasileiro, já trabalharam na estação."], ex: { t: "Copo que para de vazar", m: "um copo de plástico ou garrafinha, um lápis (com um adulto), água, um lugar aberto ou uma bacia grande", p: ["Com um adulto, faça um furinho na lateral do copo, perto do fundo, e tampe com o dedo enquanto enche de água.", "Tire o dedo: a água jorra. Tampe de novo.", "Agora, sobre a bacia ou ao ar livre, solte o copo de uma boa altura. Durante a queda, a água para de sair! Em queda livre, a água “flutua”, como na Estação Espacial."] }, at: "Emblema da missão 14", m: "papel, lápis de cor", p: ["Desenhe a Estação Espacial com seus painéis solares, com a Terra embaixo.", "Desenhe astronautas flutuando lá dentro, de cabeça para baixo e de lado.", "Faça o emblema da missão 14."], q: "O que seria mais divertido e o que seria mais difícil de morar flutuando?" },
en: { h: "Leo watched a video of astronauts playing with floating bubbles of water and wanted to know why nothing fell in there. “Actually, everything is falling!” Grandpa said. “The station, the astronauts and the water all fall together, all the time, around the Earth. That's why they float.”", t: "The International Space Station", f: "The International Space Station is a huge laboratory that circles the Earth about 400 kilometers (250 miles) up. It was built in space, piece by piece, by many countries. Since November 2000, people have always been living there, without a break.", x: "The Space Station is about the size of a football field! On the right nights, you can see it from Earth with your bare eyes, like a bright star moving quickly across the sky.", s: ["On the station, astronauts do experiments with plants, medicines, materials and their own bodies.", "Inside, it feels weightless because the station and everything in it are in free fall around the Earth.", "Astronauts from many countries, including one from Brazil, have worked on the station."], ex: { t: "The cup that stops leaking", m: "a plastic cup or small bottle, a pencil (with a grown-up), water, an open outdoor space or a big basin", p: ["With a grown-up, poke a small hole in the side of the cup near the bottom, and cover it with your finger while you fill it with water.", "Take your finger away: water squirts out. Cover it again.", "Now, over the basin or outdoors, drop the cup from a good height. While it falls, the water stops coming out! In free fall, water “floats,” just like on the Space Station."] }, at: "Mission patch 14", m: "paper, colored pencils", p: ["Draw the Space Station with its solar panels, with Earth below.", "Draw astronauts floating inside, upside down and sideways.", "Make the mission 14 patch."], q: "What would be the most fun and the hardest part of living while floating?" },
es: { h: "Leo vio un video de astronautas jugando con burbujas de agua flotando en el aire y quiso saber por qué allí no se caía nada. “¡En realidad, todo se está cayendo!”, dijo el abuelo. “La estación, los astronautas y el agua caen juntos, todo el tiempo, alrededor de la Tierra. Por eso flotan.”", t: "La Estación Espacial Internacional", f: "La Estación Espacial Internacional es un laboratorio enorme que da vueltas a la Tierra a unos 400 kilómetros de altura. Se armó en el espacio, pieza por pieza, entre varios países. Desde noviembre de 2000 siempre hay personas viviendo allí, sin parar.", x: "¡La Estación Espacial es del tamaño de una cancha de fútbol! En las noches adecuadas se la puede ver desde la Tierra a simple vista, como una estrella brillante que cruza rápido el cielo.", s: ["En la estación, los astronautas hacen experimentos con plantas, medicamentos, materiales y con su propio cuerpo.", "Adentro se siente que no se pesa nada, porque la estación y todo lo que tiene están en caída libre alrededor de la Tierra.", "Astronautas de muchos países, incluso de América Latina, ya trabajaron en la estación."], ex: { t: "El vaso que deja de gotear", m: "un vaso de plástico o botellita, un lápiz (con un adulto), agua, un lugar abierto o una palangana grande", p: ["Con un adulto, haz un agujerito al costado del vaso, cerca del fondo, y tápalo con el dedo mientras lo llenas de agua.", "Saca el dedo: el agua sale en chorro. Tápalo otra vez.", "Ahora, sobre la palangana o al aire libre, suelta el vaso desde bastante altura. ¡Mientras cae, el agua deja de salir! En caída libre el agua “flota”, como en la Estación Espacial."] }, at: "Emblema de la misión 14", m: "papel, lápices de colores", p: ["Dibuja la Estación Espacial con sus paneles solares y la Tierra abajo.", "Dibuja astronautas flotando adentro, cabeza abajo y de costado.", "Haz el emblema de la misión 14."], q: "¿Qué sería lo más divertido y lo más difícil de vivir flotando?" } },

{ e: "🌯", art: { b: "🌯", s: ["🪥", "🛏️", "🏋️", "🚽"], c: ["#2A3A4E", "#6A8AB0"] },
pt: { h: "No café da manhã, Leo deixou cair farelo de biscoito por toda a mesa. O vovô riu: “Se você fosse astronauta, esse farelo ia sair flutuando e podia entrar no nariz de alguém ou nos aparelhos da nave! Por isso eles comem tortilha em vez de pão.”", t: "A vida de um astronauta", f: "No espaço, tudo é diferente. Os astronautas dormem em sacos de dormir presos na parede, para não sair flutuando. A comida vem em pacotes, e o pão é trocado por tortilhas, que não soltam farelo. O banheiro usa um sistema de sucção, como um aspirador. E eles fazem exercício umas duas horas por dia.", x: "Sem a gravidade puxando, a coluna dos astronautas se estica, e eles podem ficar uns centímetros mais altos no espaço! Quando voltam para a Terra, encolhem de novo.", s: ["Sem exercício, os músculos e os ossos dos astronautas enfraquecem, porque não precisam sustentar o peso do corpo.", "No espaço, as lágrimas não escorrem: ficam grudadas no olho como uma bolinha de água.", "Os astronautas veem vários nasceres e pores do sol todos os dias."], ex: { t: "Farelo flutuante", m: "dois saquinhos plásticos transparentes com fecho, um biscoito, um pedaço de pão sírio ou tortilha", p: ["Coloque o biscoito num saquinho e a tortilha no outro, e feche bem.", "Esmague e chacoalhe os dois saquinhos do mesmo jeito.", "Compare: o saquinho do biscoito fica cheio de farelo, e o da tortilha quase não! No espaço, esse farelo flutuaria por toda a nave."] }, at: "Rotina espacial", m: "papel, lápis de cor", p: ["Desenhe um dia na vida de um astronauta em 6 quadrinhos: acordar, comer, trabalhar, exercitar, olhar a Terra e dormir.", "Lembre de mostrar tudo flutuando!", "Faça o emblema da missão 15."], q: "Qual parte da rotina de um astronauta você acharia mais estranha?" },
en: { h: "At breakfast, Leo dropped cookie crumbs all over the table. Grandpa laughed: “If you were an astronaut, those crumbs would float away and could get into someone's nose or into the spacecraft's equipment! That's why they eat tortillas instead of bread.”", t: "An astronaut's life", f: "In space, everything is different. Astronauts sleep in sleeping bags attached to the wall so they don't drift away. Food comes in packets, and bread is swapped for tortillas, which don't make crumbs. The toilet uses suction, like a vacuum cleaner. And they exercise about two hours a day.", x: "Without gravity pulling down, astronauts' spines stretch out, and they can get a few centimeters taller in space! When they come back to Earth, they shrink again.", s: ["Without exercise, astronauts' muscles and bones get weaker, because they don't have to hold up their body weight.", "In space, tears don't run down: they stick to the eye like a little ball of water.", "Astronauts see several sunrises and sunsets every day."], ex: { t: "Floating crumbs", m: "two clear zip-top bags, a cookie, a piece of pita bread or tortilla", p: ["Put the cookie in one bag and the tortilla in the other, and seal them tight.", "Crush and shake both bags the same way.", "Compare: the cookie bag fills up with crumbs, and the tortilla bag barely has any! In space, those crumbs would float all over the spacecraft."] }, at: "Space routine", m: "paper, colored pencils", p: ["Draw a day in an astronaut's life in 6 panels: waking up, eating, working, exercising, looking at Earth and sleeping.", "Remember to show everything floating!", "Make the mission 15 patch."], q: "Which part of an astronaut's routine would you find strangest?" },
es: { h: "En el desayuno, Leo dejó caer migas de galletita por toda la mesa. El abuelo se rió: “¡Si fueras astronauta, esas migas saldrían flotando y podrían meterse en la nariz de alguien o en los aparatos de la nave! Por eso comen tortillas en vez de pan.”", t: "La vida de un astronauta", f: "En el espacio todo es diferente. Los astronautas duermen en bolsas de dormir sujetas a la pared, para no salir flotando. La comida viene en paquetes, y el pan se cambia por tortillas, que no sueltan migas. El baño usa un sistema de succión, como una aspiradora. Y hacen ejercicio unas dos horas por día.", x: "¡Sin la gravedad tirando, la columna de los astronautas se estira, y pueden quedar unos centímetros más altos en el espacio! Cuando vuelven a la Tierra, se achican de nuevo.", s: ["Sin ejercicio, los músculos y los huesos de los astronautas se debilitan, porque no tienen que sostener el peso del cuerpo.", "En el espacio, las lágrimas no corren: se quedan pegadas al ojo como una bolita de agua.", "Los astronautas ven varios amaneceres y atardeceres todos los días."], ex: { t: "Migas flotantes", m: "dos bolsitas transparentes con cierre, una galletita, un pedazo de pan árabe o tortilla", p: ["Pon la galletita en una bolsita y la tortilla en la otra, y ciérralas bien.", "Aplasta y sacude las dos bolsitas de la misma forma.", "Compara: ¡la de la galletita se llena de migas y la de la tortilla casi nada! En el espacio, esas migas flotarían por toda la nave."] }, at: "Rutina espacial", m: "papel, lápices de colores", p: ["Dibuja un día en la vida de un astronauta en 6 cuadritos: despertarse, comer, trabajar, hacer ejercicio, mirar la Tierra y dormir.", "¡Acuérdate de mostrar todo flotando!", "Haz el emblema de la misión 15."], q: "¿Qué parte de la rutina de un astronauta te parecería más rara?" } },

{ e: "🛩️", art: { b: "🛬", s: ["🔥", "🧱", "🔭", "🌍"], c: ["#1B1B1B", "#8A8A8A"] },
pt: { h: "Leo viu a foto de uma nave espacial pousando numa pista, como um avião! “Pensei que as naves caíam no mar de paraquedas”, disse. “Algumas sim”, explicou o vovô. “Mas por 30 anos existiu uma que voltava planando e era usada de novo, como um ônibus espacial.”", t: "O ônibus espacial", f: "De 1981 a 2011, os Estados Unidos usaram os ônibus espaciais: naves com asas que subiam presas a um tanque gigante e foguetes, e voltavam planando até uma pista de pouso. Eles fizeram 135 missões, levaram astronautas de muitos países, colocaram o telescópio Hubble no espaço e ajudaram a montar a Estação Espacial.", x: "Para não queimar na volta, quando o atrito com o ar esquenta a nave a mais de mil graus, a barriga do ônibus espacial era coberta de placas especiais. Elas eram tão boas que dava para segurar uma pelas bordas logo depois de sair de um forno muito quente!", s: ["A nave voltava sem motor, planando, como um planador muito pesado.", "Cada ônibus espacial podia voar dezenas de vezes.", "Hoje os ônibus espaciais estão em museus, onde podem ser visitados."], ex: { t: "Escudo térmico", m: "três cubos de gelo iguais, papel-alumínio, um pano grosso ou algodão, um lugar ao sol", p: ["Deixe um cubo de gelo sem nada, embrulhe outro só em papel-alumínio e o terceiro em pano grosso ou algodão e depois alumínio.", "Coloque os três no sol ao mesmo tempo.", "Qual derrete por último? Bons isolantes seguram o calor do lado de fora, como as placas do ônibus espacial."] }, at: "Emblema da missão 16", m: "papel, lápis de cor", p: ["Desenhe o ônibus espacial pousando numa pista, com o paraquedas de freio aberto atrás.", "Escreva: “135 missões, 1981–2011”.", "Faça o emblema da missão 16."], q: "Por que você acha que é bom reaproveitar uma nave espacial?" },
en: { h: "Leo saw a photo of a spacecraft landing on a runway, like an airplane! “I thought spacecraft fell into the sea on parachutes,” he said. “Some do,” Grandpa explained. “But for 30 years there was one that glided home and flew again: the Space Shuttle.”", t: "The Space Shuttle", f: "From 1981 to 2011, the United States flew Space Shuttles: winged spacecraft that launched attached to a giant tank and boosters, then glided back to a runway. They flew 135 missions, carried astronauts from many countries, put the Hubble Space Telescope in orbit and helped build the Space Station.", x: "To keep from burning up on reentry, when air friction heats the craft to more than a thousand degrees, the Shuttle's belly was covered in special tiles. They were so good that you could hold one by its edges right after it came out of a very hot oven!", s: ["The Shuttle came home without engines, gliding like a very heavy glider.", "Each Shuttle could fly dozens of times.", "Today the Space Shuttles are in museums, where you can visit them."], ex: { t: "Heat shield", m: "three identical ice cubes, aluminum foil, a thick cloth or cotton, a sunny spot", p: ["Leave one ice cube bare, wrap another in just foil and the third in thick cloth or cotton and then foil.", "Put all three in the sun at the same time.", "Which melts last? Good insulators keep heat on the outside, like the Shuttle's tiles."] }, at: "Mission patch 16", m: "paper, colored pencils", p: ["Draw the Space Shuttle landing on a runway, with its drag chute open behind it.", "Write: “135 missions, 1981–2011.”", "Make the mission 16 patch."], q: "Why do you think it's good to reuse a spacecraft?" },
es: { h: "Leo vio la foto de una nave espacial aterrizando en una pista, ¡como un avión! “Pensé que las naves caían al mar en paracaídas”, dijo. “Algunas sí”, explicó el abuelo. “Pero durante 30 años hubo una que volvía planeando y se usaba otra vez: el transbordador espacial.”", t: "El transbordador espacial", f: "De 1981 a 2011, Estados Unidos usó los transbordadores espaciales: naves con alas que subían unidas a un tanque gigante y a cohetes, y volvían planeando hasta una pista de aterrizaje. Hicieron 135 misiones, llevaron astronautas de muchos países, pusieron el telescopio Hubble en el espacio y ayudaron a armar la Estación Espacial.", x: "¡Para no quemarse al volver, cuando la fricción con el aire calienta la nave a más de mil grados, la panza del transbordador estaba cubierta de placas especiales! Eran tan buenas que se podía sostener una por los bordes justo después de salir de un horno muy caliente.", s: ["La nave volvía sin motor, planeando, como un planeador muy pesado.", "Cada transbordador podía volar decenas de veces.", "Hoy los transbordadores están en museos, donde se pueden visitar."], ex: { t: "Escudo térmico", m: "tres cubitos de hielo iguales, papel de aluminio, un paño grueso o algodón, un lugar al sol", p: ["Deja un cubito sin nada, envuelve otro solo en papel de aluminio y el tercero en paño grueso o algodón y después aluminio.", "Pon los tres al sol al mismo tiempo.", "¿Cuál se derrite último? Los buenos aislantes dejan el calor afuera, como las placas del transbordador."] }, at: "Emblema de la misión 16", m: "papel, lápices de colores", p: ["Dibuja el transbordador aterrizando en una pista, con el paracaídas de frenado abierto detrás.", "Escribe: “135 misiones, 1981–2011”.", "Haz el emblema de la misión 16."], q: "¿Por qué crees que es bueno volver a usar una nave espacial?" } },

{ e: "📍", art: { b: "📡", s: ["🗺️", "🌦️", "📺", "🌳"], c: ["#0B3A3A", "#2C8A8A"] },
pt: { h: "No carro, o celular do vovô dizia: “Vire à direita em 200 metros”. Leo perguntou como o celular sabia onde eles estavam. “Ele conversa com satélites lá no espaço”, explicou o vovô. “E o Brasil também tem satélites seus, vigiando a Amazônia!”", t: "Satélites que ajudam a gente", f: "Hoje existem milhares de satélites em volta da Terra. Alguns mostram para onde vão as nuvens e ajudam a prever o tempo. Outros transmitem TV e internet. Outros formam o GPS, que mostra onde estamos. E alguns tiram fotos da Terra para vigiar florestas, plantações e cidades.", x: "Em 2021, o Brasil lançou o Amazônia-1, o primeiro satélite de observação da Terra projetado, montado e testado totalmente por brasileiros. Ele ajuda a vigiar o desmatamento da floresta!", s: ["Para o GPS saber onde você está, o celular precisa receber sinais de pelo menos quatro satélites.", "Desde 1999, o Brasil e a China constroem juntos os satélites CBERS, que fotografam a Terra.", "Os satélites de previsão do tempo ajudam a avisar as pessoas antes de tempestades fortes."], ex: { t: "GPS humano", m: "três pessoas (os satélites), barbantes do mesmo tamanho, um quintal ou sala grande", p: ["Três pessoas ficam em lugares diferentes, cada uma segurando a ponta de um barbante de uns 3 metros.", "Uma quarta pessoa, o “celular”, escolhe um lugar no meio e os três satélites esticam os barbantes até ela.", "Só existe um ponto onde as três pontas se encontram! O GPS faz isso calculando a distância até cada satélite."] }, at: "Emblema da missão 17", m: "papel, lápis de cor", p: ["Desenhe a Terra com vários satélites em volta: um de tempo, um de TV, um de GPS e o Amazônia-1 olhando a floresta.", "Escreva para que serve cada um.", "Faça o emblema da missão 17."], q: "Qual satélite você acha que mais ajuda a sua família no dia a dia?" },
en: { h: "In the car, Grandpa's phone said, “Turn right in 200 meters.” Leo asked how the phone knew where they were. “It talks to satellites up in space,” Grandpa explained. “And Brazil has satellites of its own, watching over the Amazon!”", t: "Satellites that help us", f: "Today there are thousands of satellites around the Earth. Some show where clouds are moving and help forecast the weather. Others broadcast TV and internet. Others form the GPS system, which shows where we are. And some take photos of Earth to watch over forests, farms and cities.", x: "In 2021, Brazil launched Amazonia-1, the first Earth-observation satellite designed, built and tested entirely by Brazilians. It helps monitor deforestation in the rainforest!", s: ["For GPS to know where you are, your phone needs signals from at least four satellites.", "Since 1999, Brazil and China have built CBERS satellites together to photograph the Earth.", "Weather satellites help warn people before strong storms."], ex: { t: "Human GPS", m: "three people (the satellites), strings of equal length, a yard or large room", p: ["Three people stand in different spots, each holding the end of a string about 3 meters (10 feet) long.", "A fourth person, the “phone,” picks a spot in the middle, and the three satellites stretch their strings to reach them.", "There's only one point where all three ends meet! GPS does this by calculating the distance to each satellite."] }, at: "Mission patch 17", m: "paper, colored pencils", p: ["Draw the Earth with several satellites around it: one for weather, one for TV, one for GPS and Amazonia-1 watching the forest.", "Write what each one is for.", "Make the mission 17 patch."], q: "Which satellite do you think helps your family most in everyday life?" },
es: { h: "En el auto, el celular del abuelo decía: “Gire a la derecha en 200 metros”. Leo preguntó cómo sabía el celular dónde estaban. “Conversa con satélites allá en el espacio”, explicó el abuelo. “¡Y Brasil también tiene satélites propios, vigilando la Amazonía!”", t: "Satélites que nos ayudan", f: "Hoy hay miles de satélites alrededor de la Tierra. Algunos muestran hacia dónde van las nubes y ayudan a pronosticar el tiempo. Otros transmiten televisión e internet. Otros forman el GPS, que muestra dónde estamos. Y algunos sacan fotos de la Tierra para vigilar bosques, cultivos y ciudades.", x: "¡En 2021, Brasil lanzó el Amazonia-1, el primer satélite de observación de la Tierra diseñado, armado y probado totalmente por brasileños! Ayuda a vigilar la deforestación de la selva.", s: ["Para que el GPS sepa dónde estás, el celular necesita recibir señales de al menos cuatro satélites.", "Argentina también fabrica sus propios satélites, como los ARSAT de telecomunicaciones.", "Los satélites meteorológicos ayudan a avisar a las personas antes de tormentas fuertes."], ex: { t: "GPS humano", m: "tres personas (los satélites), cordeles del mismo largo, un patio o una sala grande", p: ["Tres personas se ponen en lugares distintos, cada una sosteniendo la punta de un cordel de unos 3 metros.", "Una cuarta persona, el “celular”, elige un lugar en el medio y los tres satélites estiran los cordeles hasta ella.", "¡Hay un solo punto donde se juntan las tres puntas! El GPS hace eso calculando la distancia hasta cada satélite."] }, at: "Emblema de la misión 17", m: "papel, lápices de colores", p: ["Dibuja la Tierra con varios satélites alrededor: uno del tiempo, uno de televisión, uno de GPS y el Amazonia-1 mirando la selva.", "Escribe para qué sirve cada uno.", "Haz el emblema de la misión 17."], q: "¿Qué satélite crees que más ayuda a tu familia en el día a día?" } },

{ e: "🌎", art: { b: "🚀", s: ["🌴", "🧑‍🚀", "🌍", "⭐"], c: ["#0B4F2C", "#2C8A5A"] },
pt: { h: "O vovô mostrou no mapa uma pontinha do Maranhão, quase em cima da linha do Equador. “Aqui fica o Centro de Lançamento de Alcântara”, disse. “E sabe por que esse lugar é tão especial para lançar foguetes?” Nina e Leo giraram o globo para descobrir.", t: "O Brasil no espaço", f: "O Brasil tem uma Agência Espacial e centros de lançamento de foguetes, como o de Alcântara, no Maranhão. Em 2006, o tenente-coronel Marcos Pontes se tornou o primeiro astronauta brasileiro: ele viajou numa nave russa até a Estação Espacial Internacional e fez experimentos de escolas e cientistas do Brasil.", x: "Alcântara fica bem pertinho da linha do Equador, onde a Terra gira mais rápido. Lançar um foguete de lá é como ganhar um empurrão extra do planeta, o que economiza combustível!", s: ["Marcos Pontes passou uns dez dias no espaço e levou uma bandeira do Brasil e um uniforme da seleção.", "O Brasil também tem um centro de lançamentos em Barreira do Inferno, no Rio Grande do Norte.", "Cientistas brasileiros participam de missões espaciais e pesquisas com satélites e telescópios."], ex: { t: "O empurrão do Equador", m: "uma bola ou o globo, dois adesivos, um palito de churrasco sem ponta (eixo), uma caneta", p: ["Cole um adesivo bem no meio da bola (o Equador) e outro perto do topo (perto do polo).", "Gire a bola em volta do eixo, numa volta completa, devagar, e observe os dois adesivos.", "O adesivo do meio percorre um caminho muito maior no mesmo tempo, ou seja, anda mais rápido! Foguetes lançados perto do Equador aproveitam essa velocidade."] }, at: "Emblema da missão 18", m: "papel, lápis de cor", p: ["Desenhe um foguete subindo do litoral do Maranhão, com coqueiros e o mar.", "Desenhe também Marcos Pontes flutuando com a bandeira do Brasil.", "Faça o emblema da missão 18."], q: "Você gostaria de ser o próximo astronauta brasileiro? O que levaria para o espaço?" },
en: { h: "Grandpa showed them on the map a little tip of Maranhão, in Brazil, almost right on the equator. “This is the Alcântara Launch Center,” he said. “And do you know why it's such a special place to launch rockets?” Nina and Leo spun the globe to find out.", t: "Brazil in space", f: "Brazil has a Space Agency and rocket launch centers, like Alcântara, in the state of Maranhão. In 2006, Lieutenant Colonel Marcos Pontes became the first Brazilian astronaut: he flew on a Russian spacecraft to the International Space Station and carried out experiments from Brazilian schools and scientists.", x: "Alcântara is very close to the equator, where the Earth spins fastest. Launching a rocket from there is like getting an extra push from the planet, which saves fuel!", s: ["Marcos Pontes spent about ten days in space and took a Brazilian flag and a national soccer jersey.", "Brazil also has a launch center called Barreira do Inferno, in Rio Grande do Norte.", "Brazilian scientists take part in space missions and research with satellites and telescopes."], ex: { t: "The equator's push", m: "a ball or the globe, two stickers, a blunt bamboo skewer (as an axis), a pen", p: ["Put one sticker right in the middle of the ball (the equator) and another near the top (near the pole).", "Slowly turn the ball one full rotation around the axis and watch both stickers.", "The middle sticker travels a much longer path in the same time, so it's moving faster! Rockets launched near the equator use that extra speed."] }, at: "Mission patch 18", m: "paper, colored pencils", p: ["Draw a rocket rising from the Maranhão coast, with palm trees and the sea.", "Also draw Marcos Pontes floating with the Brazilian flag.", "Make the mission 18 patch."], q: "Would you like to be the next astronaut from your country? What would you take to space?" },
es: { h: "El abuelo mostró en el mapa una puntita de Maranhão, en Brasil, casi encima de la línea del ecuador. “Aquí está el Centro de Lanzamiento de Alcântara”, dijo. “¿Y saben por qué este lugar es tan especial para lanzar cohetes?” Nina y Leo hicieron girar el globo para descubrirlo.", t: "Sudamérica en el espacio", f: "Brasil tiene una Agencia Espacial y centros de lanzamiento de cohetes, como el de Alcântara, en Maranhão. En 2006, el teniente coronel Marcos Pontes se convirtió en el primer astronauta brasileño: viajó en una nave rusa hasta la Estación Espacial Internacional e hizo experimentos de escuelas y científicos de Brasil.", x: "¡Alcântara está muy cerca de la línea del ecuador, donde la Tierra gira más rápido! Lanzar un cohete desde allí es como recibir un empujón extra del planeta, lo que ahorra combustible.", s: ["Marcos Pontes pasó unos diez días en el espacio y llevó una bandera de Brasil y una camiseta de la selección.", "Argentina tiene su propia agencia espacial, la CONAE, y fabrica satélites.", "Científicos de toda Sudamérica participan en misiones espaciales e investigaciones con satélites y telescopios."], ex: { t: "El empujón del ecuador", m: "una pelota o el globo, dos stickers, un palito de brochette sin punta (eje), un bolígrafo", p: ["Pega un sticker justo en el medio de la pelota (el ecuador) y otro cerca de arriba (cerca del polo).", "Haz girar la pelota alrededor del eje una vuelta completa, despacio, y observa los dos stickers.", "El del medio recorre un camino mucho más largo en el mismo tiempo, ¡o sea, va más rápido! Los cohetes lanzados cerca del ecuador aprovechan esa velocidad."] }, at: "Emblema de la misión 18", m: "papel, lápices de colores", p: ["Dibuja un cohete subiendo desde la costa de Maranhão, con palmeras y el mar.", "Dibuja también a Marcos Pontes flotando con la bandera de Brasil.", "Haz el emblema de la misión 18."], q: "¿Te gustaría ser el próximo astronauta de tu país? ¿Qué llevarías al espacio?" } },

{ e: "🔭", art: { b: "🔭", s: ["🌌", "🥇", "✨", "🌀"], c: ["#1B0B3A", "#D4A82C"] },
pt: { h: "Nina olhou seu reflexo numa colher e riu: de um lado ela aparecia de cabeça para baixo, e do outro, normal. “Os telescópios espaciais usam espelhos curvos assim”, contou o vovô. “Um deles tem um espelho dourado do tamanho de uma casa!”", t: "Telescópios no espaço", f: "O ar da Terra borra a luz das estrelas, como olhar através da água. Por isso, os cientistas colocaram telescópios no espaço. O Hubble, lançado em 1990, tirou algumas das fotos mais lindas do universo. Em 2021, foi lançado o James Webb, o maior telescópio espacial já construído.", x: "O espelho do telescópio James Webb tem 6,5 metros de largura e é feito de 18 pedaços cobertos com uma camadinha de ouro! Ele enxerga a luz de galáxias que se formaram há mais de 13 bilhões de anos.", s: ["O Hubble dá uma volta na Terra a cada uns 95 minutos.", "O James Webb fica a 1,5 milhão de quilômetros da Terra, muito mais longe que a Lua.", "O Webb enxerga um tipo de luz chamado infravermelho, que é como o calor, e atravessa nuvens de poeira."], ex: { t: "Espelho de colher", m: "uma colher de metal bem limpa e brilhante", p: ["Olhe para a parte de dentro da colher (a parte côncava) bem de longe: você aparece de cabeça para baixo!", "Agora vire a colher e olhe a parte de fora (convexa): você aparece de pé e pequeninho.", "Os espelhos curvos juntam e dobram a luz. Telescópios usam espelhos curvos enormes para juntar a luz fraquinha de estrelas distantes."] }, at: "Emblema da missão 19", m: "papel preto, lápis de cor, cola com glitter (opcional)", p: ["Desenhe o espelho dourado do James Webb, feito de hexágonos, como uma colmeia.", "No fundo, desenhe galáxias e estrelas coloridas.", "Faça o emblema da missão 19."], q: "Se você tivesse um telescópio gigante, o que gostaria de enxergar?" },
en: { h: "Nina looked at her reflection in a spoon and laughed: on one side she was upside down, and on the other, right side up. “Space telescopes use curved mirrors like that,” Grandpa said. “One of them has a golden mirror as wide as a house!”", t: "Telescopes in space", f: "Earth's air blurs starlight, like looking through water. That's why scientists put telescopes in space. Hubble, launched in 1990, took some of the most beautiful pictures of the universe ever. In 2021, James Webb was launched, the largest space telescope ever built.", x: "The James Webb Space Telescope's mirror is 6.5 meters (21 feet) wide and made of 18 pieces coated with a thin layer of gold! It sees light from galaxies that formed more than 13 billion years ago.", s: ["Hubble circles the Earth about every 95 minutes.", "James Webb is 1.5 million kilometers (almost a million miles) from Earth, much farther than the Moon.", "Webb sees a kind of light called infrared, which is like heat, and can see through clouds of dust."], ex: { t: "Spoon mirror", m: "a very clean, shiny metal spoon", p: ["Look into the inside of the spoon (the concave side) from a little distance: you appear upside down!", "Now flip the spoon and look at the back (the convex side): you appear right side up and tiny.", "Curved mirrors gather and bend light. Telescopes use giant curved mirrors to collect the faint light of distant stars."] }, at: "Mission patch 19", m: "black paper, colored pencils, glitter glue (optional)", p: ["Draw James Webb's golden mirror, made of hexagons like a honeycomb.", "In the background, draw colorful galaxies and stars.", "Make the mission 19 patch."], q: "If you had a giant telescope, what would you want to see?" },
es: { h: "Nina miró su reflejo en una cuchara y se rió: de un lado aparecía cabeza abajo y del otro, normal. “Los telescopios espaciales usan espejos curvos así”, contó el abuelo. “¡Uno de ellos tiene un espejo dorado del ancho de una casa!”", t: "Telescopios en el espacio", f: "El aire de la Tierra borronea la luz de las estrellas, como mirar a través del agua. Por eso los científicos pusieron telescopios en el espacio. El Hubble, lanzado en 1990, sacó algunas de las fotos más lindas del universo. En 2021 se lanzó el James Webb, el telescopio espacial más grande jamás construido.", x: "¡El espejo del telescopio James Webb mide 6,5 metros de ancho y está hecho de 18 pedazos cubiertos con una capita de oro! Ve la luz de galaxias que se formaron hace más de 13.000 millones de años.", s: ["El Hubble da una vuelta a la Tierra cada unos 95 minutos.", "El James Webb está a 1,5 millones de kilómetros de la Tierra, mucho más lejos que la Luna.", "El Webb ve un tipo de luz llamada infrarroja, que es como el calor, y atraviesa nubes de polvo."], ex: { t: "Espejo de cuchara", m: "una cuchara de metal bien limpia y brillante", p: ["Mira la parte de adentro de la cuchara (la cóncava) desde un poco lejos: ¡apareces cabeza abajo!", "Ahora da vuelta la cuchara y mira la parte de afuera (la convexa): apareces derecho y chiquitito.", "Los espejos curvos juntan y desvían la luz. Los telescopios usan espejos curvos enormes para juntar la luz débil de estrellas lejanas."] }, at: "Emblema de la misión 19", m: "papel negro, lápices de colores, plasticola con brillantina (opcional)", p: ["Dibuja el espejo dorado del James Webb, hecho de hexágonos, como un panal.", "En el fondo, dibuja galaxias y estrellas de colores.", "Haz el emblema de la misión 19."], q: "Si tuvieras un telescopio gigante, ¿qué te gustaría ver?" } },

{ e: "🔴", art: { b: "🔴", s: ["🤖", "🚁", "🏜️", "🪨"], c: ["#5A1B0B", "#E0502C"] },
pt: { h: "Leo encontrou um prego velho e enferrujado no quintal, todo alaranjado. “Que cor é essa?”, perguntou. “É ferrugem”, disse o vovô. “E sabe qual planeta inteiro tem essa cor por causa da ferrugem? Marte! E lá tem robôs passeando agora mesmo!”", t: "Robôs em Marte", f: "Marte é chamado de planeta vermelho porque o chão dele tem muito ferro enferrujado. Como a viagem é longa e perigosa, primeiro mandamos robôs. Jipes-robôs, como o Curiosity, do tamanho de um carro, e o Perseverance, andam por lá tirando fotos, furando rochas e procurando sinais de que já existiu vida.", x: "Em 2021, um pequeno helicóptero chamado Ingenuity voou em Marte. Foi o primeiro voo motorizado da história em outro planeta! Ele levava um pedacinho do tecido da asa do avião dos irmãos Wright.", s: ["Os robôs de Marte são controlados da Terra, mas uma mensagem pode levar de 3 a mais de 20 minutos para chegar até lá.", "Os cientistas encontraram sinais de que Marte já teve rios e lagos há bilhões de anos.", "O primeiro jipe-robô em Marte, o Sojourner, de 1997, era do tamanho de um micro-ondas."], ex: { t: "Fazendo ferrugem", m: "palha de aço (sem sabão), um pote, água, um pouco de sal, um adulto", p: ["Com um adulto, coloque um pedaço de palha de aço no pote e molhe com água salgada.", "Deixe o pote aberto num cantinho por um ou dois dias e observe.", "A palha de aço fica alaranjada: é ferrugem! O ferro misturado com oxigênio e água enferruja, e foi assim que o chão de Marte ficou vermelho."] }, at: "Emblema da missão 20", m: "papel, lápis de cor vermelho e laranja", p: ["Desenhe uma paisagem de Marte com o jipe-robô e o helicóptero voando.", "Escreva o nome que você daria ao seu próprio robô de Marte.", "Faça o emblema da missão 20."], q: "O que você mandaria o seu robô procurar em Marte?" },
en: { h: "Leo found an old, rusty nail in the yard, all orange. “What color is that?” he asked. “It's rust,” Grandpa said. “And do you know which whole planet is that color because of rust? Mars! And there are robots driving around there right now!”", t: "Robots on Mars", f: "Mars is called the red planet because its ground has lots of rusty iron. Since the trip is long and dangerous, we sent robots first. Robot rovers, like Curiosity, the size of a car, and Perseverance, drive around taking pictures, drilling rocks and searching for signs that life once existed.", x: "In 2021, a small helicopter called Ingenuity flew on Mars. It was the first powered flight in history on another planet! It carried a tiny piece of fabric from the Wright brothers' airplane wing.", s: ["Mars robots are controlled from Earth, but a message can take from 3 to more than 20 minutes to get there.", "Scientists have found signs that Mars had rivers and lakes billions of years ago.", "The first rover on Mars, Sojourner, in 1997, was about the size of a microwave oven."], ex: { t: "Making rust", m: "steel wool (without soap), a jar, water, a little salt, a grown-up", p: ["With a grown-up, put a piece of steel wool in the jar and wet it with salty water.", "Leave the jar open in a corner for a day or two and watch.", "The steel wool turns orange: that's rust! Iron mixed with oxygen and water rusts, and that's how the ground on Mars turned red."] }, at: "Mission patch 20", m: "paper, red and orange colored pencils", p: ["Draw a Martian landscape with the rover and the helicopter flying.", "Write the name you would give your own Mars robot.", "Make the mission 20 patch."], q: "What would you send your robot to look for on Mars?" },
es: { h: "Leo encontró un clavo viejo y oxidado en el patio, todo anaranjado. “¿Qué color es ese?”, preguntó. “Es óxido”, dijo el abuelo. “¿Y saben qué planeta entero tiene ese color por el óxido? ¡Marte! ¡Y allí hay robots paseando ahora mismo!”", t: "Robots en Marte", f: "A Marte lo llaman el planeta rojo porque su suelo tiene mucho hierro oxidado. Como el viaje es largo y peligroso, primero mandamos robots. Vehículos robot, como el Curiosity, del tamaño de un auto, y el Perseverance, recorren el planeta sacando fotos, perforando rocas y buscando señales de que alguna vez hubo vida.", x: "¡En 2021, un pequeño helicóptero llamado Ingenuity voló en Marte! Fue el primer vuelo con motor de la historia en otro planeta. Llevaba un pedacito de la tela del ala del avión de los hermanos Wright.", s: ["Los robots de Marte se controlan desde la Tierra, pero un mensaje puede tardar de 3 a más de 20 minutos en llegar.", "Los científicos encontraron señales de que Marte tuvo ríos y lagos hace miles de millones de años.", "El primer vehículo robot en Marte, el Sojourner, de 1997, era del tamaño de un microondas."], ex: { t: "Haciendo óxido", m: "virulana (sin jabón), un frasco, agua, un poco de sal, un adulto", p: ["Con un adulto, pon un pedazo de virulana en el frasco y mójalo con agua salada.", "Deja el frasco abierto en un rincón uno o dos días y observa.", "La virulana se pone anaranjada: ¡es óxido! El hierro mezclado con oxígeno y agua se oxida, y así se puso rojo el suelo de Marte."] }, at: "Emblema de la misión 20", m: "papel, lápices rojo y naranja", p: ["Dibuja un paisaje de Marte con el vehículo robot y el helicóptero volando.", "Escribe el nombre que le pondrías a tu propio robot de Marte.", "Haz el emblema de la misión 20."], q: "¿Qué le mandarías buscar a tu robot en Marte?" } },
];
